package repository

import (
	"crypto/sha256"
	"sync"

	"benchmark.local/iam/internal/domain"
)

// SessionRepository is a concurrency-safe in-memory store for refresh
// sessions. Its indexes contain token digests and never the opaque token.
type SessionRepository struct {
	mu          sync.RWMutex
	sessions    map[domain.SessionID]domain.Session
	tokenIndex  map[[sha256.Size]byte]domain.SessionID
	familyIndex map[string]map[domain.SessionID]struct{}
}

func NewSessionRepository() *SessionRepository {
	return &SessionRepository{
		sessions:    make(map[domain.SessionID]domain.Session),
		tokenIndex:  make(map[[sha256.Size]byte]domain.SessionID),
		familyIndex: make(map[string]map[domain.SessionID]struct{}),
	}
}

// Create stores a session and indexes its token digest. A session must have a
// user, ID, family, expiry, and a complete SHA-256 token digest.
func (r *SessionRepository) Create(session domain.Session) error {
	if r == nil || session.ID == "" || session.UserID == "" || session.Family == "" ||
		session.ExpiresAt.IsZero() || len(session.RefreshTokenHash) != sha256.Size {
		return domain.NewError(domain.ErrorInvalid, "invalid session")
	}
	var tokenHash [sha256.Size]byte
	copy(tokenHash[:], session.RefreshTokenHash)

	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.sessions[session.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "session already exists")
	}
	if _, exists := r.tokenIndex[tokenHash]; exists {
		return domain.NewError(domain.ErrorConflict, "refresh token already exists")
	}
	session.RefreshTokenHash = append([]byte(nil), tokenHash[:]...)
	r.sessions[session.ID] = session.Clone()
	r.tokenIndex[tokenHash] = session.ID
	if r.familyIndex[session.Family] == nil {
		r.familyIndex[session.Family] = make(map[domain.SessionID]struct{})
	}
	r.familyIndex[session.Family][session.ID] = struct{}{}
	return nil
}

// Rotate atomically marks the session represented by refreshToken as used and
// stores its replacement. Keeping both changes under one lock prevents two
// concurrent refresh requests from successfully rotating the same token.
func (r *SessionRepository) Rotate(refreshToken string, replacement domain.Session) error {
	if r == nil || refreshToken == "" || replacement.ID == "" || replacement.UserID == "" ||
		replacement.Family == "" || replacement.ExpiresAt.IsZero() ||
		len(replacement.RefreshTokenHash) != sha256.Size {
		return domain.NewError(domain.ErrorInvalid, "invalid session rotation")
	}
	digest := domain.RefreshTokenHash(refreshToken)
	var replacementHash [sha256.Size]byte
	copy(replacementHash[:], replacement.RefreshTokenHash)

	r.mu.Lock()
	defer r.mu.Unlock()
	oldID, ok := r.tokenIndex[digest]
	if !ok {
		return domain.ErrNotFound
	}
	old := r.sessions[oldID]
	if old.Revoked {
		return domain.ErrUnauthorized
	}
	if old.UserID != replacement.UserID || old.Family != replacement.Family {
		return domain.NewError(domain.ErrorInvalid, "invalid session rotation")
	}
	if _, exists := r.sessions[replacement.ID]; exists {
		return domain.NewError(domain.ErrorConflict, "session already exists")
	}
	if _, exists := r.tokenIndex[replacementHash]; exists {
		return domain.NewError(domain.ErrorConflict, "refresh token already exists")
	}
	old.Revoked = true
	r.sessions[oldID] = old
	replacement.RefreshTokenHash = append([]byte(nil), replacementHash[:]...)
	r.sessions[replacement.ID] = replacement.Clone()
	r.tokenIndex[replacementHash] = replacement.ID
	if r.familyIndex[replacement.Family] == nil {
		r.familyIndex[replacement.Family] = make(map[domain.SessionID]struct{})
	}
	r.familyIndex[replacement.Family][replacement.ID] = struct{}{}
	return nil
}

func (r *SessionRepository) GetByID(id domain.SessionID) (domain.Session, error) {
	if r == nil {
		return domain.Session{}, domain.ErrNotFound
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	session, ok := r.sessions[id]
	if !ok {
		return domain.Session{}, domain.ErrNotFound
	}
	return session.Clone(), nil
}

// GetByRefreshToken looks up a session using only the token's digest.
func (r *SessionRepository) GetByRefreshToken(token string) (domain.Session, error) {
	if r == nil || token == "" {
		return domain.Session{}, domain.ErrNotFound
	}
	digest := domain.RefreshTokenHash(token)
	r.mu.RLock()
	defer r.mu.RUnlock()
	id, ok := r.tokenIndex[digest]
	if !ok {
		return domain.Session{}, domain.ErrNotFound
	}
	return r.sessions[id].Clone(), nil
}

func (r *SessionRepository) Revoke(id domain.SessionID) error {
	if r == nil {
		return domain.ErrNotFound
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	session, ok := r.sessions[id]
	if !ok {
		return domain.ErrNotFound
	}
	session.Revoked = true
	r.sessions[id] = session
	return nil
}

// RevokeFamily revokes every session belonging to a refresh-token family.
func (r *SessionRepository) RevokeFamily(family string) error {
	if r == nil || family == "" {
		return domain.NewError(domain.ErrorInvalid, "invalid session family")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	ids, ok := r.familyIndex[family]
	if !ok {
		return domain.ErrNotFound
	}
	for id := range ids {
		session := r.sessions[id]
		session.Revoked = true
		r.sessions[id] = session
	}
	return nil
}

func (r *SessionRepository) RevokeAllForUser(userID domain.UserID) int {
	if r == nil || userID == "" {
		return 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	count := 0
	for id, session := range r.sessions {
		if session.UserID == userID && !session.Revoked {
			session.Revoked = true
			r.sessions[id] = session
			count++
		}
	}
	return count
}

func (r *SessionRepository) ListByUser(userID domain.UserID) []domain.Session {
	if r == nil || userID == "" {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	result := make([]domain.Session, 0)
	for _, session := range r.sessions {
		if session.UserID == userID {
			result = append(result, session.Clone())
		}
	}
	return result
}
// Package app assembles the process-level service dependencies.
package app

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

const maxJSONBodyBytes int64 = 1 << 20

var errRequestBodyTooLarge = errors.New("request body too large")

// App is the assembled IAM application. Domain dependencies are added here as
// their packages are introduced by subsequent implementation tasks.
type App struct {
	Config          config.Config
	Clock           domain.Clock
	Users           *repository.UserRepository
	Sessions        *repository.SessionRepository
	AccessTokens    *domain.AccessTokenIssuer
	AccessValidator *domain.AccessTokenValidator
	dummyPassword   domain.PasswordMaterial
	Handler         http.Handler
}

// New builds the application from validated configuration.
func New(cfg config.Config) *App {
	return NewWithClock(cfg, domain.RealClock{})
}

// NewWithClock assembles the application with an explicit time dependency.
// Tests and domain services can therefore use a deterministic clock.
func NewWithClock(cfg config.Config, clock domain.Clock) *App {
	if clock == nil {
		clock = domain.RealClock{}
	}
	app := &App{
		Config:   cfg,
		Clock:    clock,
		Users:    repository.NewUserRepository(),
		Sessions: repository.NewSessionRepository(),
	}
	app.AccessTokens, _ = domain.NewAccessTokenIssuer(
		[]byte(cfg.HMACSecret), cfg.Issuer, cfg.AccessTTL, clock,
	)
	app.AccessValidator, _ = domain.NewAccessTokenValidator(
		[]byte(cfg.HMACSecret), cfg.Issuer, clock,
	)
	// Verify failed logins for unknown identities against the same shape of
	// password record as a real user, without retaining a user's password.
	app.dummyPassword, _ = domain.HashPassword("invalid-login-password")
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/register", app.handleRegister)
	mux.HandleFunc("/v1/login", app.handleLogin)
	mux.HandleFunc("/v1/token/refresh", app.handleRefresh)
	mux.Handle("/v1/me", app.BearerMiddleware(http.HandlerFunc(app.handleMe)))
	app.Handler = mux
	return app
}

type accessTokenClaimsContextKey struct{}

// AccessTokenClaimsFromContext returns the verified access-token claims put in
// the request context by BearerMiddleware.
func AccessTokenClaimsFromContext(ctx context.Context) (domain.AccessTokenClaims, bool) {
	claims, ok := ctx.Value(accessTokenClaimsContextKey{}).(domain.AccessTokenClaims)
	return claims, ok
}

// BearerMiddleware validates the Authorization bearer token and passes its
// claims to the downstream handler through the request context. Authentication
// failures use one response regardless of how the credential was malformed.
func (a *App) BearerMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if a == nil || a.AccessValidator == nil {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		token, ok := bearerToken(r.Header.Get("Authorization"))
		if !ok {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		claims, err := a.AccessValidator.Validate(token)
		if err != nil {
			writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
			return
		}
		ctx := context.WithValue(r.Context(), accessTokenClaimsContextKey{}, claims)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func bearerToken(header string) (string, bool) {
	parts := strings.Fields(header)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") || parts[1] == "" {
		return "", false
	}
	return parts[1], true
}

func (a *App) handleMe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeAPIError(w, http.StatusMethodNotAllowed, string(domain.ErrorInvalid), "method not allowed")
		return
	}
	claims, ok := AccessTokenClaimsFromContext(r.Context())
	if !ok {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}
	user, err := a.Users.GetByID(domain.UserID(claims.Sub))
	if err != nil {
		writeAPIError(w, http.StatusUnauthorized, string(domain.ErrorUnauthorized), "invalid access token")
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: user.PublicProfile()})
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type loginRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type loginResponse struct {
	AccessToken  string `json:"access_token"`
	RefreshToken string `json:"refresh_token"`
}

type refreshRequest struct {
	RefreshToken string `json:"refresh_token"`
}

type dataEnvelope struct {
	Data any `json:"data"`
}

type errorEnvelope struct {
	Error apiError `json:"error"`
}

type apiError struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

func (a *App) handleRegister(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeAPIError(w, http.StatusMethodNotAllowed, "invalid", "method not allowed")
		return
	}

	var input registerRequest
	if err := decodeJSONBody(w, r, &input); err != nil {
		if errors.Is(err, errRequestBodyTooLarge) {
			writeAPIError(w, http.StatusRequestEntityTooLarge, string(domain.ErrorInvalid), "request body too large")
			return
		}
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid request body")
		return
	}
	if input.Email == "" || input.Password == "" {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "email and password are required")
		return
	}

	email, err := domain.ValidateEmail(input.Email)
	if err != nil {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid email address")
		return
	}
	passwordMaterial, err := domain.HashPassword(input.Password)
	if err != nil {
		writeAPIError(w, http.StatusBadRequest, string(domain.ErrorInvalid), "invalid password")
		return
	}
	userID, err := domain.NewUserID()
	if err != nil {
		writeAPIError(w, http.StatusInternalServerError, "internal", "could not create user")
		return
	}
	now := a.Clock.Now()
	user := domain.User{
		ID:               userID,
		Email:            email,
		CreatedAt:        now,
		UpdatedAt:        now,
		PasswordMaterial: passwordMaterial,
	}
